#!/usr/bin/env python3
"""Python re-implementation of src/program.cbl (BOOKFORUM)."""

from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent
DATA_DIR = BASE_DIR / "data"
INPUT_PATH = BASE_DIR / "src" / "INPUT.DAT"

ACCOUNTS_PATH = DATA_DIR / "ACCOUNTS.DAT"
BOOKS_PATH = DATA_DIR / "BOOKS.DAT"
TRANSACTIONS_PATH = DATA_DIR / "TRANSACTIONS.DAT"

ACCOUNT_LEN = 34
BOOK_LEN = 28
TRANSACTION_LEN = 22
INPUT_LEN = 22

TEN_DIGIT_MOD = 10_000_000_000
U64_MASK = (1 << 64) - 1


class Record:
    """One record read from a COBOL sequential file.

    ``data`` is the full COBOL record area.  For an incomplete final record,
    bytes beyond the bytes actually read retain the previous record's data
    (as in libcob).  ``chunk`` is the actual data read from the file, so an
    incomplete record can be written back unchanged.
    """

    __slots__ = ("data", "chunk", "complete", "rewritten")

    def __init__(self, chunk, buffer, record_length):
        self.chunk = chunk
        self.data = bytes(buffer)
        self.complete = len(chunk) == record_length
        self.rewritten = False

    def serialize(self):
        if self.rewritten:
            return self.data
        return self.chunk


def read_records(path, record_length):
    content = path.read_bytes()
    records = []
    buffer = bytearray(record_length)
    for offset in range(0, len(content), record_length):
        chunk = content[offset : offset + record_length]
        buffer[0 : len(chunk)] = chunk
        records.append(Record(chunk, buffer, record_length))
    return records


def write_records(path, records):
    path.write_bytes(b"".join(r.serialize() for r in records))


def parse_display_field(data):
    """Return the (unscaled) value GnuCOBOL gets from a DISPLAY numeric field.

    These fields have fewer than 20 digits, so libcob accumulates each byte
    as ``byte - ord('0')`` in a 64-bit unsigned value, after skipping leading
    bytes whose low nibble is zero.  The two special first-byte cases below
    match cob_decimal_set_display.
    """
    size = len(data)
    if size == 0:
        return 0

    if data[0] == 0xFF:
        return 10**size
    if data[0] == 0:
        return -(10**size)

    start = 0
    remaining = size
    while remaining > 1 and (data[start] & 0x0F) == 0:
        start += 1
        remaining -= 1

    value = 0
    for byte in data[start : start + remaining]:
        value = ((value * 10) + (byte - 0x30)) & U64_MASK
    return value


def trunc_div(numerator, denominator):
    """C-style integer division (truncation toward zero)."""
    if numerator < 0:
        return -((-numerator) // denominator)
    return numerator // denominator


def store_unsigned_10(value):
    """Store a value in an unsigned PIC 9(10) COBOL field."""
    if value < 0:
        value = -value
    value %= TEN_DIGIT_MOD
    return f"{value:010d}".encode("ascii")


def load_amount_field(input_record):
    """Return the 12 display bytes of WS-AMOUNT PIC 9(10)V99 after MOVE."""
    source = input_record[12:22]
    result = bytearray(12)
    for i, byte in enumerate(source):
        # Numeric MOVE turns space/NUL padding into '0'.
        result[i] = 0x30 if byte in (0, 0x20) else byte
    result[10] = 0x30
    result[11] = 0x30
    return bytes(result)


def account_balance_after(balance_field, amount_value, subtract):
    """Perform the COBOL ADD/SUBTRACT and store into PIC 9(10)."""
    balance_value = parse_display_field(balance_field)
    balance_scale = 0
    amount_scale = 2

    scale = max(balance_scale, amount_scale)
    scaled_balance = balance_value * (10 ** (scale - balance_scale))
    scaled_amount = amount_value * (10 ** (scale - amount_scale))

    if subtract:
        result = scaled_balance - scaled_amount
    else:
        result = scaled_balance + scaled_amount

    # Store into the account field, which has scale 0.
    if scale > 0:
        result = trunc_div(result, 10**scale)
    return store_unsigned_10(result)


def main():
    try:
        input_records = read_records(INPUT_PATH, INPUT_LEN)
    except FileNotFoundError:
        return

    if not input_records:
        print("Error: Input file is empty")
        return

    input_record = input_records[0].data

    buyer_id = input_record[0:4]
    seller_id = input_record[4:8]
    book_id = input_record[8:12]

    ws_amount_raw = load_amount_field(input_record)
    amount_value = parse_display_field(ws_amount_raw)

    try:
        accounts = read_records(ACCOUNTS_PATH, ACCOUNT_LEN)
        books = read_records(BOOKS_PATH, BOOK_LEN)
    except FileNotFoundError:
        return

    buyer_found = False
    seller_found = False
    book_found = False
    valid_owner = False

    for record in accounts:
        account_id = record.data[0:4]
        if account_id == buyer_id:
            buyer_found = True
        if account_id == seller_id:
            seller_found = True

    for record in books:
        if record.data[0:4] == book_id:
            book_found = True
            if record.data[24:28] == seller_id:
                valid_owner = True

    print(" ")

    if not (buyer_found and seller_found and book_found and valid_owner):
        print("Transaction failed due to validation errors")
        return

    # PROCESS-TRANSACTION: update accounts.
    if buyer_id == seller_id:
        # With the same buyer and seller, GnuCOBOL performs the buyer's
        # REWRITE and then fails on the second REWRITE (no READ in between),
        # terminating the run before BOOKS/TRANSACTIONS are touched.
        for record in accounts:
            if record.data[0:4] == buyer_id:
                if not record.complete:
                    # An incomplete final record is not a successful READ,
                    # so REWRITE fails immediately.
                    return
                new_balance = account_balance_after(
                    record.data[24:34], amount_value, subtract=True
                )
                record.data = (
                    record.data[:24] + new_balance + record.data[34:]
                )
                record.rewritten = True
                write_records(ACCOUNTS_PATH, accounts)
                return
    else:
        for record in accounts:
            account_id = record.data[0:4]

            if account_id == buyer_id:
                if not record.complete:
                    write_records(ACCOUNTS_PATH, accounts)
                    return
                new_balance = account_balance_after(
                    record.data[24:34], amount_value, subtract=True
                )
                record.data = (
                    record.data[:24] + new_balance + record.data[34:]
                )
                record.rewritten = True

            if account_id == seller_id:
                if not record.complete:
                    write_records(ACCOUNTS_PATH, accounts)
                    return
                new_balance = account_balance_after(
                    record.data[24:34], amount_value, subtract=False
                )
                record.data = (
                    record.data[:24] + new_balance + record.data[34:]
                )
                record.rewritten = True

    write_records(ACCOUNTS_PATH, accounts)

    # PROCESS-TRANSACTION: update the book owner.
    for record in books:
        if record.data[0:4] == book_id:
            if not record.complete:
                write_records(BOOKS_PATH, books)
                return
            record.data = (
                record.data[:24] + buyer_id + record.data[28:]
            )
            record.rewritten = True

    write_records(BOOKS_PATH, books)

    # PROCESS-TRANSACTION: append the transaction.
    transaction = (
        book_id + ws_amount_raw[0:10] + seller_id + buyer_id
    )
    with TRANSACTIONS_PATH.open("ab") as transaction_file:
        transaction_file.write(transaction)

    print("Transaction completed successfully")


if __name__ == "__main__":
    main()
PY
